SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET QUOTED_IDENTIFIER ON;
SET NUMERIC_ROUNDABORT OFF;
SET LOCK_TIMEOUT 5000;
DECLARE @Apply bit = 0;
PRINT N'Chạy với @Apply = 0 để xem trước. Sau khi duyệt, đổi @Apply = 1 và chạy lại toàn bộ file để lưu.';
PRINT N'Chỉ làm mới nội dung hiển thị seed đã kiểm kê. Không chạy lại file tạo bảng hoặc seed gốc.';
IF DB_NAME() <> N'UTEFitDB' THROW 51900, 'Select UTEFitDB in SSMS before running this file.', 1;
IF @@TRANCOUNT <> 0 THROW 51901, 'Use a new independent SSMS query window.', 1;
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'UTEFit.DemoSeed.Version' AND CONVERT(nvarchar(100),value)=N'V712-demo55')
    THROW 51902, 'Expected V712-demo55 seed marker. This script does not modify database purpose or Live approval.', 1;
DECLARE @Changes TABLE (
    table_name sysname NOT NULL,
    id bigint NOT NULL,
    expected_identity nvarchar(max) NOT NULL,
    expected_content nvarchar(max) NOT NULL,
    proposed_content nvarchar(max) NOT NULL,
    PRIMARY KEY (table_name,id)
);

INSERT @Changes (table_name,id,expected_identity,expected_content,proposed_content) VALUES
(N'branches', 1, N'{"id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"name":"UTEFit - Chi nhánh 1","address":"Địa chỉ chi nhánh demo 1","phone":"0000001001","description":""}', N'{"name":"UTEFit - Chi nhánh 1","address":"68 Đường Nguyễn Thị Minh Khai, khu vực Đa Kao, Quận 1, TP.HCM (địa chỉ minh họa)","phone":"028 0000 1001","description":"Không gian luyện tập hiện đại với khu vực tập sức mạnh, vận động toàn thân và các lớp theo lịch. Phù hợp để sắp xếp buổi tập trước hoặc sau giờ làm. Địa chỉ và số liên hệ chỉ dùng minh họa cho đồ án, không đại diện cơ sở kinh doanh thực tế."}'),
(N'branches', 2, N'{"id":2,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"name":"UTEFit - Chi nhánh 2","address":"Địa chỉ chi nhánh demo 2","phone":"0000001002","description":""}', N'{"name":"UTEFit - Chi nhánh 2","address":"142 Đường Võ Văn Tần, khu vực Võ Thị Sáu, Quận 3, TP.HCM (địa chỉ minh họa)","phone":"028 0000 1002","description":"Không gian tập luyện được bố trí theo từng nhóm bài tập, giúp hội viên dễ làm quen với thiết bị và theo dõi lịch lớp. Các buổi yoga và hướng dẫn kỹ thuật hỗ trợ duy trì thói quen vận động. Địa chỉ và số liên hệ chỉ dùng minh họa cho đồ án."}'),
(N'branches', 3, N'{"id":3,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"name":"UTEFit - Chi nhánh 3","address":"Địa chỉ chi nhánh demo 3","phone":"0000001003","description":""}', N'{"name":"UTEFit - Chi nhánh 3","address":"26 Đường Nguyễn Thị Thập, khu vực Tân Phú, Quận 7, TP.HCM (địa chỉ minh họa)","phone":"028 0000 1003","description":"Điểm tập hướng đến nhịp sinh hoạt linh hoạt, kết hợp luyện thể lực, yoga và hướng dẫn kỹ thuật. Hội viên có thể xem lớp và buổi huấn luyện ngay trên lịch cá nhân. Địa chỉ và số liên hệ chỉ dùng minh họa cho đồ án."}'),
(N'branches', 4, N'{"id":4,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"name":"UTEFit - Chi nhánh 4","address":"Địa chỉ chi nhánh demo 4","phone":"0000001004","description":""}', N'{"name":"UTEFit - Chi nhánh 4","address":"215 Đường Xô Viết Nghệ Tĩnh, khu vực Phường 21, Bình Thạnh, TP.HCM (địa chỉ minh họa)","phone":"028 0000 1004","description":"Không gian tập luyện dành cho hội viên muốn rèn sức mạnh và duy trì vận động đều đặn. Lịch lớp được phân chia rõ theo khung giờ để thuận tiện lựa chọn. Địa chỉ và số liên hệ chỉ dùng minh họa cho đồ án."}'),
(N'branches', 5, N'{"id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"name":"UTEFit - Chi nhánh 5","address":"Địa chỉ chi nhánh demo 5","phone":"0000001005","description":""}', N'{"name":"UTEFit - Chi nhánh 5","address":"125 Đường Võ Văn Ngân, khu vực Linh Chiểu, TP. Thủ Đức, TP.HCM (địa chỉ minh họa)","phone":"028 0000 1005","description":"Không gian luyện tập trẻ trung, phù hợp với người mới bắt đầu và hội viên muốn xây dựng lịch tập ổn định. Kết hợp các lớp thể lực, yoga và hướng dẫn kỹ thuật vận động. Địa chỉ và số liên hệ chỉ dùng minh họa cho đồ án."}');

