INSERT @Changes (table_name,id,expected_identity,expected_content,proposed_content) VALUES
(N'trainers', 1, N'{"id":1,"user_id":31,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Thể hình và sức mạnh nền tảng","years_experience":5,"bio":"Tôi hướng dẫn các bài tập thể hình nền tảng, chú trọng tư thế và cách kiểm soát chuyển động. Mỗi buổi tập được điều chỉnh theo thể lực và mục tiêu của hội viên."}'),
(N'trainers', 2, N'{"id":2,"user_id":32,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Yoga cơ bản và kéo giãn","years_experience":4,"bio":"Tôi đồng hành cùng hội viên trong các bài yoga cơ bản và luyện nhịp thở. Cách hướng dẫn chậm rãi giúp người mới làm quen với từng tư thế và duy trì sự thoải mái khi tập."}'),
(N'trainers', 3, N'{"id":3,"user_id":33,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Huấn luyện cá nhân và kỹ thuật vận động","years_experience":3,"bio":"Tôi tập trung vào kỹ thuật tập luyện cá nhân và xây dựng thói quen vận động đều đặn. Trong buổi tập, hội viên được hướng dẫn khởi động, thực hành và thả lỏng theo trình tự rõ ràng."}'),
(N'trainers', 4, N'{"id":4,"user_id":34,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Cardio và tăng sức bền","years_experience":4,"bio":"Tôi hướng dẫn cardio và các bài rèn sức bền theo nhịp độ phù hợp. Hội viên được theo dõi cảm nhận vận động để biết khi nào cần điều chỉnh cường độ hoặc nghỉ giữa hiệp."}'),
(N'trainers', 5, N'{"id":5,"user_id":35,"branch_id":2,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Thể hình và sức mạnh nền tảng","years_experience":6,"bio":"Tôi yêu thích việc giúp hội viên làm quen với tạ và các thiết bị trong phòng tập. Mục tiêu của mỗi buổi là thực hiện động tác có kiểm soát và tăng dần mức vận động phù hợp."}'),
(N'trainers', 6, N'{"id":6,"user_id":36,"branch_id":2,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Yoga cơ bản và kéo giãn","years_experience":3,"bio":"Tôi hướng dẫn yoga kết hợp các bài kéo giãn nhẹ nhàng. Hội viên có thể trao đổi về mức độ thoải mái để lựa chọn biến thể tư thế phù hợp trong buổi tập."}'),
(N'trainers', 7, N'{"id":7,"user_id":37,"branch_id":2,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Huấn luyện cá nhân và kỹ thuật vận động","years_experience":4,"bio":"Tôi chú trọng xây dựng nền tảng chuyển động trước khi tăng độ khó của bài tập. Hội viên được hướng dẫn từng bước để hiểu cách thực hiện và tự tin hơn khi luyện tập."}'),
(N'trainers', 8, N'{"id":8,"user_id":38,"branch_id":2,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Cardio và tăng sức bền","years_experience":5,"bio":"Tôi đồng hành cùng hội viên qua các bài cardio và vận động toàn thân. Các khoảng vận động, nghỉ ngơi được sắp xếp rõ ràng để buổi tập vừa sức và dễ theo dõi."}'),
(N'trainers', 9, N'{"id":9,"user_id":39,"branch_id":3,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Thể hình và sức mạnh nền tảng","years_experience":4,"bio":"Tôi tập trung vào các bài thể hình cơ bản và kỹ thuật sử dụng máy tập. Tôi khuyến khích hội viên ghi nhận quá trình luyện tập để duy trì nhịp vận động đều đặn."}'),
(N'trainers', 10, N'{"id":10,"user_id":40,"branch_id":3,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Yoga cơ bản và kéo giãn","years_experience":5,"bio":"Tôi hướng dẫn yoga với sự chú ý đến nhịp thở và khả năng vận động của từng người. Buổi tập có những khoảng chuyển tiếp nhẹ nhàng để hội viên làm quen với chuỗi tư thế."}'),
(N'trainers', 11, N'{"id":11,"user_id":41,"branch_id":3,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Huấn luyện cá nhân và kỹ thuật vận động","years_experience":3,"bio":"Tôi hướng dẫn luyện tập cá nhân dựa trên mục tiêu và lịch sinh hoạt của hội viên. Các động tác được chia thành từng bước để người tập dễ ghi nhớ và thực hành."}'),
(N'trainers', 12, N'{"id":12,"user_id":42,"branch_id":3,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Cardio và tăng sức bền","years_experience":4,"bio":"Tôi phụ trách các bài cardio và rèn sức bền dành cho người muốn duy trì vận động thường xuyên. Tôi ưu tiên nhịp tập rõ ràng, động tác vừa sức và thời gian phục hồi phù hợp."}'),
(N'trainers', 13, N'{"id":13,"user_id":43,"branch_id":4,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Thể hình và sức mạnh nền tảng","years_experience":5,"bio":"Tôi hướng dẫn các bài tập sức mạnh với tạ và thiết bị hỗ trợ. Trong mỗi buổi tập, tư thế và nhịp thực hiện luôn được trao đổi trước khi điều chỉnh mức tạ."}'),
(N'trainers', 14, N'{"id":14,"user_id":44,"branch_id":4,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Yoga cơ bản và kéo giãn","years_experience":4,"bio":"Tôi đồng hành cùng hội viên trong các bài yoga nền tảng và kéo giãn. Tôi dành thời gian giải thích từng tư thế để người mới có thể theo dõi buổi tập một cách thoải mái."}'),
(N'trainers', 15, N'{"id":15,"user_id":45,"branch_id":4,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Huấn luyện cá nhân và kỹ thuật vận động","years_experience":3,"bio":"Tôi hướng dẫn kỹ thuật luyện tập cá nhân, từ khởi động đến các bài vận động chính. Mỗi buổi đều có phần trao đổi ngắn để điều chỉnh nội dung theo khả năng thực tế."}'),
(N'trainers', 16, N'{"id":16,"user_id":46,"branch_id":4,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Cardio và tăng sức bền","years_experience":4,"bio":"Tôi tập trung vào các bài cardio có nhịp độ linh hoạt và vận động toàn thân. Hội viên được hướng dẫn lựa chọn mức vận động phù hợp để duy trì buổi tập một cách chủ động."}'),
(N'trainers', 17, N'{"id":17,"user_id":47,"branch_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Thể hình và sức mạnh nền tảng","years_experience":6,"bio":"Tôi hướng dẫn thể hình và các bài rèn sức mạnh nền tảng. Tôi chú trọng việc quan sát động tác, giải thích ngắn gọn và hỗ trợ hội viên điều chỉnh khi cần."}'),
(N'trainers', 18, N'{"id":18,"user_id":48,"branch_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Yoga cơ bản và kéo giãn","years_experience":3,"bio":"Tôi hướng dẫn yoga cơ bản kết hợp nhịp thở và kéo giãn. Buổi tập ưu tiên sự tập trung, chuyển động có kiểm soát và cảm nhận thoải mái của hội viên."}'),
(N'trainers', 19, N'{"id":19,"user_id":49,"branch_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Huấn luyện cá nhân và kỹ thuật vận động","years_experience":5,"bio":"Tôi đồng hành cùng hội viên trong các buổi luyện kỹ thuật và xây dựng nền tảng thể lực. Nội dung được sắp xếp theo từng bước để người tập hiểu rõ mục tiêu của buổi."}'),
(N'trainers', 20, N'{"id":20,"user_id":50,"branch_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"specialization":"Gym / Yoga / PT - DEMO","years_experience":2,"bio":"Fictional development trainer, no real personal data."}', N'{"specialization":"Cardio và tăng sức bền","years_experience":4,"bio":"Tôi hướng dẫn cardio và những bài vận động phù hợp với lịch tập thường ngày. Tôi khuyến khích hội viên duy trì nhịp luyện tập vừa sức và chú ý đến thời gian nghỉ."}');

INSERT @Changes (table_name,id,expected_identity,expected_content,proposed_content) VALUES
(N'reviews', 1, N'{"id":1,"user_id":12,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Không gian tập thoáng, các khu vực được bố trí dễ tìm. Mình thấy thuận tiện khi xem lịch lớp trước khi đến tập. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 2, N'{"id":2,"user_id":14,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Huấn luyện viên giải thích động tác rõ ràng và nhắc mình điều chỉnh tư thế. Cách hướng dẫn từng bước rất phù hợp với người mới. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 3, N'{"id":3,"user_id":15,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Mình thích cách sắp xếp thiết bị theo nhóm bài tập. Buổi đầu làm quen với phòng tập khá nhẹ nhàng và dễ theo dõi. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 4, N'{"id":4,"user_id":15,"branch_id":2,"trainer_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Lịch lớp hiển thị rõ khung giờ nên mình chủ động chọn buổi phù hợp. Thao tác đăng ký trên website cũng khá thuận tiện. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 5, N'{"id":5,"user_id":17,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Không khí tập luyện thoải mái, phần khởi động được hướng dẫn kỹ. Mình có thêm động lực duy trì lịch tập đều đặn. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 6, N'{"id":6,"user_id":18,"branch_id":2,"trainer_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Khu vực tập gọn gàng và dụng cụ dễ sử dụng. Khi cần hỗ trợ, mình được giải thích ngắn gọn, dễ hiểu. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 7, N'{"id":7,"user_id":19,"branch_id":3,"trainer_id":9,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Buổi tập có nhịp độ vừa sức, thời gian nghỉ giữa các bài được sắp xếp hợp lý. Mình có thể theo dõi nội dung buổi tập mà không bị vội. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 8, N'{"id":8,"user_id":20,"branch_id":4,"trainer_id":13,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Mình đánh giá cao cách huấn luyện viên quan sát và góp ý trong lúc thực hiện động tác. Những hướng dẫn nhỏ giúp mình tự tin hơn. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 9, N'{"id":9,"user_id":21,"branch_id":5,"trainer_id":17,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Phòng tập sạch sẽ, không gian dễ chịu và lịch lớp khá linh hoạt. Mình dễ tìm được buổi phù hợp với thời gian rảnh. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 10, N'{"id":10,"user_id":22,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Việc xem lại lịch tập và thông tin chi nhánh trên website rất tiện. Nội dung được trình bày rõ, không mất nhiều thời gian tìm kiếm. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 11, N'{"id":11,"user_id":23,"branch_id":2,"trainer_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Lớp yoga có phần hướng dẫn nhịp thở và chuyển tư thế chậm rãi. Mình cảm thấy thoải mái khi làm quen với các động tác cơ bản. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 12, N'{"id":12,"user_id":24,"branch_id":3,"trainer_id":9,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Thiết bị được sắp xếp ngăn nắp, lối đi giữa các khu vực khá thuận tiện. Mình có thể tập trung hơn vào các bài tập trong buổi. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 13, N'{"id":13,"user_id":25,"branch_id":4,"trainer_id":13,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Mình thích phần hướng dẫn kỹ thuật trước khi bắt đầu bài chính. Huấn luyện viên giải thích mục tiêu của từng động tác khá dễ hiểu. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 14, N'{"id":14,"user_id":26,"branch_id":5,"trainer_id":17,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Trải nghiệm đăng ký lớp và theo dõi lịch trên website khá liền mạch. Khi mở chi tiết buổi tập, thông tin giờ và địa điểm rất rõ ràng. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 15, N'{"id":15,"user_id":27,"branch_id":1,"trainer_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Khung giờ buổi sáng phù hợp với lịch sinh hoạt của mình. Buổi tập được chia thành các phần rõ ràng, từ khởi động đến thả lỏng. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 16, N'{"id":16,"user_id":28,"branch_id":2,"trainer_id":5,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Không gian tập có cảm giác gần gũi, không quá áp lực với người mới. Mình được nhắc chọn mức vận động phù hợp thay vì tập quá sức. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 17, N'{"id":17,"user_id":29,"branch_id":3,"trainer_id":9,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Mình dễ theo dõi những buổi đã đăng ký và chủ động sắp xếp thời gian. Đây là điểm hữu ích khi kết hợp tập luyện với lịch học và làm việc. (Đánh giá minh họa cho đồ án.)"}'),
(N'reviews', 18, N'{"id":18,"user_id":30,"branch_id":4,"trainer_id":13,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"comment":"DEMO: fictional gym experience, seeded for development only."}', N'{"comment":"Buổi tập được chuẩn bị gọn gàng, phần hướng dẫn có ví dụ cụ thể. Mình muốn tiếp tục giữ thói quen vận động và theo dõi tiến độ qua lịch cá nhân. (Đánh giá minh họa cho đồ án.)"}');

