(N'personal_training_schedules', 1, N'{"id":1,"trainer_id":1,"member_id":12,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"title":"DEMO PT session","note":"Development only"}', N'{"title":"PT 1:1 - Nền tảng sức bền","note":"Khởi động nhẹ, làm quen với các động tác nền tảng và điều chỉnh nhịp tập theo khả năng. Chuẩn bị trang phục thoải mái và trao đổi với huấn luyện viên trước buổi tập."}'),
(N'personal_training_schedules', 2, N'{"id":2,"trainer_id":1,"member_id":14,"branch_id":1,"created_at":"2026-10-30T01:33:22.6861979"}', N'{"title":"DEMO PT session","note":"Development only"}', N'{"title":"PT 1:1 - Kỹ thuật và thể lực","note":"Ôn lại kỹ thuật vận động cơ bản, thực hành bài tập có hướng dẫn và thả lỏng cuối buổi. Xem lại ngày, giờ trên lịch cá nhân trước khi đến tập."}');

INSERT @Changes (table_name,id,expected_identity,expected_content,proposed_content) VALUES
(N'trainer_requests', 1, N'{"id":1,"member_id":12,"trainer_id":1,"requested_at":"2026-10-30T01:33:22.6861979"}', N'{"message":"DEMO accepted coaching request"}', N'{"message":"Mình muốn cải thiện sức bền và làm quen với các động tác cơ bản. Mong huấn luyện viên hướng dẫn cách xây dựng lịch tập vừa sức."}'),
(N'trainer_requests', 2, N'{"id":2,"member_id":14,"trainer_id":1,"requested_at":"2026-10-30T01:33:22.6861979"}', N'{"message":"DEMO accepted coaching request"}', N'{"message":"Mình muốn được hướng dẫn kỹ thuật và duy trì thói quen tập luyện đều đặn. Nhờ huấn luyện viên hỗ trợ lựa chọn nội dung phù hợp."}');

