(N'messages', 2, N'{"id":2,"conversation_id":1,"sender_id":31,"sent_at":"2026-10-30T01:33:22.6861979"}', N'{"content":"DEMO: Your session is scheduled."}', N'{"content":"Anh đã sắp xếp buổi tập trong lịch cá nhân. Em kiểm tra ngày, giờ ở mục Lịch tập và dành thời gian khởi động trước buổi tập nhé."}');

