IF (SELECT COUNT(*) FROM @Changes) <> 248 THROW 51903, 'Expected exactly 248 reviewed records.', 1;
IF EXISTS (SELECT 1 FROM @Changes WHERE ISJSON(expected_identity)<>1 OR ISJSON(expected_content)<>1 OR ISJSON(proposed_content)<>1)
    THROW 51904, 'Invalid reviewed content manifest.', 1;
DECLARE @UnicodeColumns TABLE (table_name sysname, column_name sysname, characters int, nullable bit, PRIMARY KEY(table_name,column_name));
INSERT @UnicodeColumns VALUES
(N'branches',N'name',150,0),
(N'branches',N'address',255,0),
(N'branches',N'description',1000,1),
(N'users',N'first_name',50,0),
(N'users',N'last_name',50,0),
(N'trainers',N'specialization',255,1),
(N'trainers',N'bio',2000,1),
(N'reviews',N'comment',2000,1),
(N'class_categories',N'name',100,0),
(N'class_categories',N'description',1000,1),
(N'fitness_classes',N'name',150,0),
(N'fitness_classes',N'description',1500,1),
(N'class_schedules',N'room',100,1),
(N'membership_plans',N'description',1500,1),
(N'personal_training_schedules',N'title',255,1),
(N'personal_training_schedules',N'note',2000,1),
(N'trainer_requests',N'message',2000,1),
(N'messages',N'content',2000,0),
(N'notifications',N'title',200,0),
(N'notifications',N'content',2000,1);
IF EXISTS (
    SELECT 1 FROM @UnicodeColumns target
    LEFT JOIN sys.tables tables ON tables.name=target.table_name AND tables.schema_id=SCHEMA_ID(N'dbo')
    LEFT JOIN sys.columns columns ON columns.object_id=tables.object_id AND columns.name=target.column_name
    WHERE columns.column_id IS NULL OR TYPE_NAME(columns.user_type_id) NOT IN (N'varchar',N'nvarchar')
       OR columns.is_nullable<>target.nullable
       OR columns.max_length<>target.characters * CASE TYPE_NAME(columns.user_type_id) WHEN N'nvarchar' THEN 2 ELSE 1 END
) THROW 51905, 'Display column schema changed; review Unicode widening before continuing.', 1;
IF EXISTS (SELECT 1 FROM sys.triggers WHERE is_disabled=0 AND parent_id IN (
    SELECT OBJECT_ID(N'dbo.' + table_name) FROM @Changes
)) THROW 51906, 'An enabled trigger exists on a target table. Review its side effects first.', 1;
IF (SELECT COUNT(*) FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id) <> 5
    THROW 51910, 'branches: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id WHERE EXISTS (SELECT t.[id], t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.description') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'branches: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[users] t JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id) <> 40
    THROW 51910, 'users: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[users] t JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id WHERE EXISTS (SELECT t.[id], CONVERT(nvarchar(max), t.[email]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[role]) COLLATE Latin1_General_100_BIN2, t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), JSON_VALUE(p.expected_identity, N'$.email') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.expected_identity, N'$.role') COLLATE Latin1_General_100_BIN2, TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.last_name') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.last_name') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'users: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[trainers] t JOIN @Changes p ON p.table_name = N'trainers' AND p.id = t.id) <> 20
    THROW 51910, 'trainers: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[trainers] t JOIN @Changes p ON p.table_name = N'trainers' AND p.id = t.id WHERE EXISTS (SELECT t.[id], t.[user_id], t.[branch_id], t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.user_id')), TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.branch_id')), TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[specialization]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[years_experience]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[bio]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.specialization') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.years_experience') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.bio') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[specialization]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[years_experience]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[bio]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.specialization') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.years_experience') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.bio') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'trainers: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[reviews] t JOIN @Changes p ON p.table_name = N'reviews' AND p.id = t.id) <> 18
    THROW 51910, 'reviews: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[reviews] t JOIN @Changes p ON p.table_name = N'reviews' AND p.id = t.id WHERE EXISTS (SELECT t.[id], t.[user_id], t.[branch_id], t.[trainer_id], t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.user_id')), TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.branch_id')), TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.trainer_id')), TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[comment]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.comment') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[comment]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.comment') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'reviews: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[class_categories] t JOIN @Changes p ON p.table_name = N'class_categories' AND p.id = t.id) <> 3
    THROW 51910, 'class_categories: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[class_categories] t JOIN @Changes p ON p.table_name = N'class_categories' AND p.id = t.id WHERE EXISTS (SELECT t.[id], t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.description') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'class_categories: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[fitness_classes] t JOIN @Changes p ON p.table_name = N'fitness_classes' AND p.id = t.id) <> 15
    THROW 51910, 'fitness_classes: missing audited records; stop and inspect.', 1;
