DECLARE @Pending TABLE (table_name sysname, id bigint, PRIMARY KEY(table_name,id));
INSERT @Pending SELECT N'branches', t.id FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'users', t.id FROM dbo.[users] t JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.last_name') COLLATE Latin1_General_100_BIN2);
