INSERT @Pending SELECT N'reviews', t.id FROM dbo.[reviews] t JOIN @Changes p ON p.table_name = N'reviews' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[comment]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.comment') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'class_categories', t.id FROM dbo.[class_categories] t JOIN @Changes p ON p.table_name = N'class_categories' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'fitness_classes', t.id FROM dbo.[fitness_classes] t JOIN @Changes p ON p.table_name = N'fitness_classes' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'class_schedules', t.id FROM dbo.[class_schedules] t JOIN @Changes p ON p.table_name = N'class_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[room]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.room') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'membership_plans', t.id FROM dbo.[membership_plans] t JOIN @Changes p ON p.table_name = N'membership_plans' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'personal_training_schedules', t.id FROM dbo.[personal_training_schedules] t JOIN @Changes p ON p.table_name = N'personal_training_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[note]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.note') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'trainer_requests', t.id FROM dbo.[trainer_requests] t JOIN @Changes p ON p.table_name = N'trainer_requests' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[message]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.message') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'messages', t.id FROM dbo.[messages] t JOIN @Changes p ON p.table_name = N'messages' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2);
INSERT @Pending SELECT N'notifications', t.id FROM dbo.[notifications] t JOIN @Changes p ON p.table_name = N'notifications' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2);
SELECT p.table_name AS bang, COUNT(*) AS ban_ghi_duoc_duyet,
       SUM(CASE WHEN pending.id IS NULL THEN 0 ELSE 1 END) AS ban_ghi_can_cap_nhat
FROM @Changes p LEFT JOIN @Pending pending ON pending.table_name=p.table_name AND pending.id=p.id GROUP BY p.table_name ORDER BY p.table_name;
SELECT p.table_name AS bang,p.id,p.expected_content AS noi_dung_seed_goc,p.proposed_content AS noi_dung_moi,
       CASE WHEN pending.id IS NULL THEN N'Đã đúng nội dung mới' ELSE N'Chờ duyệt cập nhật' END AS trang_thai
FROM @Changes p LEFT JOIN @Pending pending ON pending.table_name=p.table_name AND pending.id=p.id ORDER BY p.table_name,p.id;
SELECT target.table_name AS bang,target.column_name AS cot,TYPE_NAME(columns.user_type_id) AS kieu_hien_tai,
       CONCAT(N'nvarchar(',target.characters,N')') AS kieu_unicode
FROM @UnicodeColumns target JOIN sys.columns columns ON columns.object_id=OBJECT_ID(N'dbo.'+target.table_name) AND columns.name=target.column_name
WHERE TYPE_NAME(columns.user_type_id)=N'varchar' ORDER BY target.table_name,target.column_name;
IF @Apply = 0
BEGIN
    PRINT N'CHỈ XEM TRƯỚC: chưa đổi schema, chưa cập nhật dữ liệu. Đổi @Apply = 1 sau khi duyệt để thực hiện.';
    RETURN;
END;
DECLARE @BeforeProtected TABLE (table_name sysname,id bigint,fingerprint varbinary(32),PRIMARY KEY(table_name,id));
DECLARE @AfterProtected TABLE (table_name sysname,id bigint,fingerprint varbinary(32),PRIMARY KEY(table_name,id));
DECLARE @Applied TABLE (table_name sysname,id bigint,PRIMARY KEY(table_name,id));
BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @lockResult int;
    EXEC @lockResult=sys.sp_getapplock @Resource=N'UTEFit.DemoContent.20261030',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=5000;
    IF @lockResult<0 THROW 51907, 'Cannot acquire content update lock.', 1;
IF (SELECT COUNT(*) FROM dbo.[branches] t WITH (UPDLOCK, HOLDLOCK) JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id) <> 5
    THROW 51910, 'branches: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[branches] t WITH (UPDLOCK, HOLDLOCK) JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id WHERE EXISTS (SELECT t.[id], t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.description') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2)))
    THROW 51911, 'branches: seed identity or content changed; stop without overwriting user edits.', 1;
IF (SELECT COUNT(*) FROM dbo.[users] t WITH (UPDLOCK, HOLDLOCK) JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id) <> 40
    THROW 51910, 'users: missing audited records; stop and inspect.', 1;
IF EXISTS (SELECT 1 FROM dbo.[users] t WITH (UPDLOCK, HOLDLOCK) JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id WHERE EXISTS (SELECT t.[id], CONVERT(nvarchar(max), t.[email]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[role]) COLLATE Latin1_General_100_BIN2, t.[created_at] EXCEPT SELECT TRY_CONVERT(bigint, JSON_VALUE(p.expected_identity, N'$.id')), JSON_VALUE(p.expected_identity, N'$.email') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.expected_identity, N'$.role') COLLATE Latin1_General_100_BIN2, TRY_CONVERT(datetime2(7), JSON_VALUE(p.expected_identity, N'$.created_at'), 126)) OR (EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[expected_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[expected_content], N'$.last_name') COLLATE Latin1_General_100_BIN2) AND EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.last_name') COLLATE Latin1_General_100_BIN2)))
