    UPDATE t SET [name] = JSON_VALUE(p.proposed_content, N'$.name'), [address] = JSON_VALUE(p.proposed_content, N'$.address'), [phone] = JSON_VALUE(p.proposed_content, N'$.phone'), [description] = JSON_VALUE(p.proposed_content, N'$.description')
    OUTPUT N'branches', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [first_name] = JSON_VALUE(p.proposed_content, N'$.first_name'), [last_name] = JSON_VALUE(p.proposed_content, N'$.last_name')
    OUTPUT N'users', inserted.id INTO @Applied(table_name,id)
