    UPDATE t SET [specialization] = JSON_VALUE(p.proposed_content, N'$.specialization'), [years_experience] = TRY_CONVERT(int, JSON_VALUE(p.proposed_content, N'$.years_experience')), [bio] = JSON_VALUE(p.proposed_content, N'$.bio')
    OUTPUT N'trainers', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[trainers] t JOIN @Changes p ON p.table_name = N'trainers' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[specialization]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[years_experience]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[bio]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.specialization') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.years_experience') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.bio') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [comment] = JSON_VALUE(p.proposed_content, N'$.comment')
    OUTPUT N'reviews', inserted.id INTO @Applied(table_name,id)
