    UPDATE t SET [name] = JSON_VALUE(p.proposed_content, N'$.name'), [description] = JSON_VALUE(p.proposed_content, N'$.description')
    OUTPUT N'fitness_classes', inserted.id INTO @Applied(table_name,id)
