    UPDATE t SET [room] = JSON_VALUE(p.proposed_content, N'$.room')
    OUTPUT N'class_schedules', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[class_schedules] t JOIN @Changes p ON p.table_name = N'class_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[room]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.room') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [description] = JSON_VALUE(p.proposed_content, N'$.description')
