    UPDATE t SET [title] = JSON_VALUE(p.proposed_content, N'$.title'), [note] = JSON_VALUE(p.proposed_content, N'$.note')
    OUTPUT N'personal_training_schedules', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[personal_training_schedules] t JOIN @Changes p ON p.table_name = N'personal_training_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[note]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.note') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [message] = JSON_VALUE(p.proposed_content, N'$.message')
    OUTPUT N'trainer_requests', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[trainer_requests] t JOIN @Changes p ON p.table_name = N'trainer_requests' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[message]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.message') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [content] = JSON_VALUE(p.proposed_content, N'$.content')
    OUTPUT N'messages', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[messages] t JOIN @Changes p ON p.table_name = N'messages' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2);
    UPDATE t SET [title] = JSON_VALUE(p.proposed_content, N'$.title'), [content] = JSON_VALUE(p.proposed_content, N'$.content')
    OUTPUT N'notifications', inserted.id INTO @Applied(table_name,id)
    FROM dbo.[notifications] t JOIN @Changes p ON p.table_name = N'notifications' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2);
    IF EXISTS (SELECT table_name,id FROM @Pending EXCEPT SELECT table_name,id FROM @Applied)
       OR EXISTS (SELECT table_name,id FROM @Applied EXCEPT SELECT table_name,id FROM @Pending)
        THROW 51920, 'Updated row set differs from approved pending row set.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[address]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[phone]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.address') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.phone') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'branches: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[users] t JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[first_name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[last_name]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.first_name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.last_name') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'users: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[trainers] t JOIN @Changes p ON p.table_name = N'trainers' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[specialization]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[years_experience]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[bio]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.specialization') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.years_experience') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.bio') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'trainers: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[reviews] t JOIN @Changes p ON p.table_name = N'reviews' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[comment]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.comment') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'reviews: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[class_categories] t JOIN @Changes p ON p.table_name = N'class_categories' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'class_categories: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[fitness_classes] t JOIN @Changes p ON p.table_name = N'fitness_classes' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[name]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.name') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'fitness_classes: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[class_schedules] t JOIN @Changes p ON p.table_name = N'class_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[room]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.room') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'class_schedules: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[membership_plans] t JOIN @Changes p ON p.table_name = N'membership_plans' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[description]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.description') COLLATE Latin1_General_100_BIN2))
