    IF EXISTS (SELECT 1 FROM dbo.[personal_training_schedules] t JOIN @Changes p ON p.table_name = N'personal_training_schedules' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[note]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.note') COLLATE Latin1_General_100_BIN2))
