    IF EXISTS (SELECT 1 FROM dbo.[trainer_requests] t JOIN @Changes p ON p.table_name = N'trainer_requests' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[message]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.message') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'trainer_requests: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[messages] t JOIN @Changes p ON p.table_name = N'messages' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'messages: persisted display content differs; rollback.', 1;
    IF EXISTS (SELECT 1 FROM dbo.[notifications] t JOIN @Changes p ON p.table_name = N'notifications' AND p.id = t.id WHERE EXISTS (SELECT CONVERT(nvarchar(max), t.[title]) COLLATE Latin1_General_100_BIN2, CONVERT(nvarchar(max), t.[content]) COLLATE Latin1_General_100_BIN2 EXCEPT SELECT JSON_VALUE(p.[proposed_content], N'$.title') COLLATE Latin1_General_100_BIN2, JSON_VALUE(p.[proposed_content], N'$.content') COLLATE Latin1_General_100_BIN2))
        THROW 51921, 'notifications: persisted display content differs; rollback.', 1;
    IF (SELECT COUNT(DISTINCT JSON_VALUE(proposed_content,N'$.comment')) FROM @Changes WHERE table_name=N'reviews')<>18
        THROW 51922, 'Expected 18 different illustrative review comments.', 1;
    INSERT @AfterProtected
    SELECT N'branches', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[closing_time], t.[opening_time], t.[created_at], t.[id], t.[updated_at], t.[image_public_id], t.[image_url] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[branches] t JOIN @Changes p ON p.table_name = N'branches' AND p.id = t.id
    UNION ALL
    SELECT N'users', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[enabled], t.[token_version], t.[created_at], t.[id], t.[updated_at], t.[phone], t.[role], t.[status], t.[email], t.[avatar_public_id], t.[avatar_url], t.[password] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[users] t JOIN @Changes p ON p.table_name = N'users' AND p.id = t.id
    UNION ALL
    SELECT N'trainers', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[branch_id], t.[created_at], t.[id], t.[updated_at], t.[user_id] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[trainers] t JOIN @Changes p ON p.table_name = N'trainers' AND p.id = t.id
    UNION ALL
    SELECT N'reviews', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[rating], t.[visible], t.[branch_id], t.[created_at], t.[id], t.[trainer_id], t.[updated_at], t.[user_id], t.[image_url], t.[video_url], t.[image_public_id], t.[video_public_id] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[reviews] t JOIN @Changes p ON p.table_name = N'reviews' AND p.id = t.id
    UNION ALL
    SELECT N'class_categories', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[created_at], t.[id], t.[updated_at], t.[required_benefit] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[class_categories] t JOIN @Changes p ON p.table_name = N'class_categories' AND p.id = t.id
    UNION ALL
    SELECT N'fitness_classes', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[capacity], t.[branch_id], t.[category_id], t.[created_at], t.[id], t.[trainer_id], t.[updated_at], t.[status] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[fitness_classes] t JOIN @Changes p ON p.table_name = N'fitness_classes' AND p.id = t.id
    UNION ALL
    SELECT N'class_schedules', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[end_time], t.[schedule_date], t.[start_time], t.[created_at], t.[fitness_class_id], t.[id] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[class_schedules] t JOIN @Changes p ON p.table_name = N'class_schedules' AND p.id = t.id
    UNION ALL
    SELECT N'membership_plans', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[duration_days], t.[price], t.[created_at], t.[id], t.[updated_at], t.[name], t.[benefit], t.[access_scope], t.[duration_unit], t.[duration_quantity], t.[bonus_unit], t.[bonus_quantity] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[membership_plans] t JOIN @Changes p ON p.table_name = N'membership_plans' AND p.id = t.id
    UNION ALL
    SELECT N'personal_training_schedules', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[active], t.[end_time], t.[schedule_date], t.[start_time], t.[branch_id], t.[created_at], t.[id], t.[member_id], t.[trainer_id], t.[updated_at], t.[status] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[personal_training_schedules] t JOIN @Changes p ON p.table_name = N'personal_training_schedules' AND p.id = t.id
    UNION ALL
    SELECT N'trainer_requests', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[id], t.[member_id], t.[requested_at], t.[responded_at], t.[trainer_id], t.[status] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[trainer_requests] t JOIN @Changes p ON p.table_name = N'trainer_requests' AND p.id = t.id
    UNION ALL
    SELECT N'messages', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[conversation_id], t.[id], t.[read_at], t.[sender_id], t.[sent_at] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[messages] t JOIN @Changes p ON p.table_name = N'messages' AND p.id = t.id
    UNION ALL
    SELECT N'notifications', t.id, HASHBYTES('SHA2_256', CONVERT(varbinary(max), (SELECT t.[is_read], t.[created_at], t.[id], t.[read_at], t.[related_id], t.[user_id], t.[type] FOR JSON PATH, INCLUDE_NULL_VALUES, WITHOUT_ARRAY_WRAPPER))) FROM dbo.[notifications] t JOIN @Changes p ON p.table_name = N'notifications' AND p.id = t.id;
    IF EXISTS (SELECT table_name,id,fingerprint FROM @BeforeProtected EXCEPT SELECT table_name,id,fingerprint FROM @AfterProtected)
       OR EXISTS (SELECT table_name,id,fingerprint FROM @AfterProtected EXCEPT SELECT table_name,id,fingerprint FROM @BeforeProtected)
        THROW 51923, 'A protected column changed; rollback all updates.', 1;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
